            continue  # warm-up period, no signals

        prior_highest_close = df['close'].iloc[i - n + 1:i].max()
        prior_lowest_close = df['close'].iloc[i - n + 1:i].min()

        if df['close'].iloc[i] > prior_highest_close and signals.iloc[i - 1] == 0:
            signals.iloc[i] = 1  # long
