def generate_signals(df: pd.DataFrame) -> pd.Series:
    n = 120
    rsi_n = 4

    # Calculate SMA and RSI
    df['SMA'] = df['close'].rolling(window=n, min_periods=n).mean()
    df['RSI'] = np.nan
    df.loc[rsi_n, 'RSI'] = 100
    for i in range(rsi_n, len(df)):
        gain = np.maximum(df.loc[i, 'close'] - df.loc[i-1, 'close'], 0)
        loss = np.maximum(-df.loc[i, 'close'] + df.loc[i-1, 'close'], 0)
        avg_gain = np.where(loss == 0, 0, gain + (gain - df.loc[i-1, 'avg_gain']) / rsi_n)
        avg_loss = loss + (loss - df.loc[i-1, 'avg_loss']) / rsi_n
        df.loc[i, 'RSI'] = 100 - 100 / (1 + avg_gain / avg_loss)
        df.loc[i, 'avg_gain'] = avg_gain
        df.loc[i, 'avg_loss'] = avg_loss

    # Initialize signals
    signals = pd.Series(index=df.index, data=0)

    # Initialize warm-up period
    warm_up = n

    # Loop over bars
    for i in range(len(df)):
        # If in warm-up period, keep flat
        if i < warm_up:
            signals.loc[i] = 0
        else:
            # If long, check exit conditions
            if signals.loc[i-1] == 1:
                if df.loc[i, 'RSI'] > 55 or df.loc[i, 'close'] < df.loc[i, 'SMA']:
                    signals.loc[i] = 0
                else:
                    signals.loc[i] = 1
            # If short, check exit conditions
            elif signals.loc[i-1] == -1:
                if df.loc[i, 'RSI'] < 45 or df.loc[i, 'close'] > df.loc[i, 'SMA']:
                    signals.loc[i] = 0
                else:
                    signals.loc[i] = -1
            # If flat, check entry conditions
            else:
                if df.loc[i, 'close'] > df.loc[i, 'SMA'] and df.loc[i, 'RSI'] < 40:
                    signals.loc[i] = 1
                elif df.loc[i, 'close'] < df.loc[i, 'SMA'] and df.loc[i, 'RSI'] > 60:
                    signals.loc[i] = -1
                else:
                    signals.loc[i] = 0

    return signals

