def generate_signals(df: pd.DataFrame) -> pd.Series:
    n = 40
    warm_up = n - 1

    # Calculate SMA and PSTD
    df['SMA'] = df['close'].rolling(n).mean()
    df['PSTD'] = df['close'].rolling(n).std() / n
    df['upper'] = df['SMA'] + 2 * df['PSTD']
    df['lower'] = df['SMA'] - 2 * df['PSTD']

    # Initialize position
    positions = pd.Series(0, index=df.index)

    # Loop over bars
    for i in range(warm_up, len(df)):
        # If flat, check if close < lower or close > upper
        if positions.iloc[i-1] == 0:
            if df.loc[i, 'close'] < df.loc[i, 'lower']:
                positions.iloc[i] = 1
            elif df.loc[i, 'close'] > df.loc[i, 'upper']:
                positions.iloc[i] = -1
            else:
                positions.iloc[i] = 0

        # If long, check if close >= middle
        elif positions.iloc[i-1] == 1:
            if df.loc[i, 'close'] >= df.loc[i, 'SMA']:
                positions.iloc[i] = 0
            else:
                positions.iloc[i] = 1

        # If short, check if close <= middle
        elif positions.iloc[i-1] == -1:
            if df.loc[i, 'close'] <= df.loc[i, 'SMA']:
                positions.iloc[i] = 0
            else:
                positions.iloc[i] = -1

        # Otherwise keep the current position
        else:
            positions.iloc[i] = positions.iloc[i-1]

    return positions

