                signals[i] = -1
        elif signals[i-1] == 1:
            if df['close'][i] < df['SMA'][i] and df['close'][i-1] >= df['SMA'][i-1]:
                signals[i] = 0
            elif df['close'][i] < df['close'][i-1] * (1 - 0.03):
                signals[i] = 0
        elif signals[i-1] == -1:
            if df['close'][i] > df['SMA'][i] and df['close'][i-1] <= df['SMA'][i-1]:
                signals[i] = 0
            elif df['close'][i] > df['close'][i-1] * (1 + 0.03):
                signals[i] = 0

    return signals
